/* ---------- theorie: lesstof en vragen (bron: Flagship Academy SOR Theorie, 19 mei 2026) ---------- */
/* Vraag: q = vraag, a = [goed antwoord, fout, fout, fout], u = uitleg, p = pagina in het theorieboek */
const LEER_ALL=[
{id:'wet',t:'Wet- en regelgeving',kort:'BPR, CVO en documenten aan boord',p:8,
 intro:'Het kennen van de regels voor varen op de grachten: inzicht in vergunningen, snelheidslimieten, veiligheidsvoorschriften, milieuregels en de verantwoordelijkheden van handhavende instanties.',
 les:[
  {t:'Regels op het water',p:9,b:['In principe zijn alle regels die je hebt geleerd voor het **Klein Vaarbewijs** voldoende om dit examen te halen.','Fris daarom je kennis op over onder andere **verkeersborden, voorrangsregels, verlichting en scheepstypen** met het Klein Vaarbewijs-boek. Deze regels worden in de opleiding niet opnieuw volledig herhaald.','De focus ligt op het correct toepassen van de regels in de praktijk en het kunnen uitleggen van je keuzes tijdens het examen.']},
  {t:'BPR',p:9,b:['Het Binnenvaartpolitiereglement (BPR) geldt op de binnenwateren van **Nederland en de Waddenzee**, met uitzondering van onder meer de Rijntakken.',{tip:'Op de **Boven-Rijn, Waal, Pannerdensch Kanaal, Neder-Rijn en Lek** geldt niet het BPR maar het **RPR** (Rijnvaartpolitiereglement).'},'Kennis van het BPR is nodig voor een veilige vaart en een vereiste voor het kwalificatiecertificaat ‘Schipper open rondvaartboot’.','**Het BPR moet altijd aan boord zijn**, digitaal of op papier.','Je hoeft niet alle regels uit je hoofd te kennen, maar je moet wel weten waar je informatie **terugvindt** en hoe je het reglement gebruikt.']},
  {t:'Scheepsadministratie',p:10,b:['Alle documenten en registraties over **het schip zelf**: de identiteit van het schip, waarvoor het gebruikt mag worden en onder welke voorwaarden. De administratie laat zien dat het schip **goedgekeurd, vergund en veilig inzetbaar** is.','Hier horen onder andere bij:',['**CVO** (Certificaat van Onderzoek) en eventueel CBB: leidend document voor keuring, uitrusting en vaargebied','**Exploitatievergunning** (bijvoorbeeld A1)','**Logboek** van het schip. Bij open sloepen geen vaartijdenboek, maar wel een logboek waarin staat dat de boot vaart (zoals L1nda of Shiftbase)'],'Als schipper moet je weten welke administratie van toepassing is, waar die aan boord ligt, en kunnen uitleggen wat het schip wel en niet mag.',{tip:'Bij twijfel over gebruik, uitrusting of vaargebied is het **CVO altijd leidend**.'}]},
  {t:'Verordening 2010',p:11,b:['Een lokale wet van de **gemeente Amsterdam**. Geldt alleen op de Amsterdamse binnenwateren, zoals de grachten, het IJ en de Amstel.','De verordening beschrijft hoe het water gebruikt mag worden en onder welke voorwaarden:',['aanvragen van vergunningen','gebruik van het vaarwater','overlast, woonboten','ligplaatsen bedrijfsvaartuigen','vervoer van passagiers (waaronder rondvaart) en vergunningen daarvoor','vervoer van goederen, waaronder gevaarlijke stoffen','pleziervaartuigen'],'Kennis hiervan is raadzaam voor bedrijfsmatig varen in Amsterdam, maar het is **niet opgenomen in de exameneisen van het CBR**.']},
  {t:'CVO en CBB',p:11,b:['Het CVO (Certificaat van Onderzoek) vormt de technische en juridische basis van het schip. Het laat zien dat het schip is goedgekeurd en onder welke **voorwaarden** het mag worden ingezet.','Het CVO geeft onder andere informatie over:',['het **vaargebied** waarvoor het schip is goedgekeurd','de maximale belading en het toegestane **gebruik**','de verplichte **veiligheidsuitrusting**','de **geldigheidsduur** van de keuring'],'Het CBB bevat aanvullende of specifieke voorwaarden voor het schip en de inrichting.','De schipper moet weten waar het CVO (en eventueel het CBB) aan boord ligt, en het kunnen **lezen, interpreteren en toepassen**. Bij twijfel over uitrusting (lijnen, brandblussers, anker), gebruik of vaargebied is het CVO leidend, tijdens de vaart en bij een controle of examen.',{tip:'Tijdens het CBR-examen kun je gevraagd worden: aanwijzen waar het CVO ligt, uitleggen wat erin staat, laten zien tot wanneer het geldig is en toelichten welke beperkingen gelden.'}]},
  {t:'Documenten aan boord',p:13,b:['Documenten mogen op papier of digitaal aan boord zijn, zolang ze **direct raadpleegbaar** zijn.','Verplicht:',['Het CVO','Vaarbewijs of EU-certificaat','Marifoonbewijs','BPR (digitaal of fysiek)','Waterkaart (digitaal of fysiek)'],'Daarnaast moet je basiskennis hebben van **AIS**, de **tachograaf** en **Vesselfinder**. Let op: Vesselfinder is géén waterkaart en vervangt geen nautische kaart.']}
 ],
 cbr:['Welke documenten moet je aan boord hebben?','Wat is het belangrijkste onderdeel van het CVO?','Welke verkeerstekens, gebodstekens en verbodstekens kom je tegen op het water?','Wat zijn de voorrangsregels tussen kleine en grote schepen?','Hoe herken je of een schip als groot of klein schip wordt aangemerkt?','Wat is het verschil tussen hoofdvaarwater en nevenvaarwater?'],
 v:[
  {q:'Waar geldt het BPR?',a:['Op de Nederlandse binnenwateren en de Waddenzee, behalve onder meer de Rijntakken','Op alle Nederlandse binnenwateren, dus ook op de Waal, de Lek en de Neder-Rijn','Alleen op de grote rivieren en kanalen, maar niet op de Amsterdamse grachten','Op de Noordzee en de Waddenzee, maar niet op de Nederlandse binnenwateren'],u:'Het BPR geldt op de binnenwateren van Nederland en de Waddenzee. Op de Rijntakken (Boven-Rijn, Waal, Pannerdensch Kanaal, Neder-Rijn en Lek) geldt het RPR.',p:9},
  {q:'Welk reglement geldt op de Waal?',a:['Het RPR (Rijnvaartpolitiereglement)','Het BPR (Binnenvaartpolitiereglement)','De Verordening 2010','Het Scheepvaartreglement Westerschelde'],u:'Op de Rijntakken, zoals de Boven-Rijn, Waal, Pannerdensch Kanaal, Neder-Rijn en Lek, geldt het RPR en niet het BPR.',p:9},
  {q:'Op welke vaarwegen geldt het RPR in plaats van het BPR?',a:['Op de Boven-Rijn, Waal, Pannerdensch Kanaal, Neder-Rijn en Lek','Op het IJ, het Noordzeekanaal, het Markermeer en de grachten','Op het IJsselmeer, de Waddenzee en de Zeeuwse wateren','Op de Maas, de Vecht, de Zaan en de Amstel'],u:'Op de Boven-Rijn, Waal, Pannerdensch Kanaal, Neder-Rijn en Lek geldt het RPR (Rijnvaartpolitiereglement), niet het BPR.',p:9},
  {q:'Wat wordt van je verwacht over de regels in het BPR?',a:['Je moet weten waar je de informatie terugvindt en hoe je het reglement gebruikt','Je moet alle artikelen van het BPR letterlijk uit je hoofd kunnen opzeggen','Je moet vooral de Verordening 2010 kennen; het BPR is voor de grote vaart','Je hoeft alleen de regels over verlichting en geluidsseinen te kennen'],u:'Je hoeft niet alles uit je hoofd te kennen, maar je moet wel weten waar je informatie terugvindt.',p:9},
  {q:'Je twijfelt over de uitrusting, het gebruik of het vaargebied van je schip. Welk document is leidend?',a:['Het CVO (Certificaat van Onderzoek)','De exploitatievergunning (bijvoorbeeld A1)','Het logboek van het schip','De nautische waterkaart'],u:'Bij twijfel over uitrusting, gebruik of vaargebied is het CVO altijd leidend.',p:12},
  {q:'Welke informatie staat in het CVO?',a:['Vaargebied, maximale belading en gebruik, veiligheidsuitrusting en geldigheidsduur','Vaargebied, vaarroutes, dienstrooster van de schippers en de ligplaats','Maximale belading, namen van de passagiers, tarieven en vaartijden','Veiligheidsuitrusting, actuele waterstand, stremmingen en brughoogtes'],u:'Het CVO noemt onder andere het vaargebied, de maximale belading en het gebruik, de verplichte veiligheidsuitrusting en de geldigheidsduur van de keuring.',p:11},
  {q:'Mag je Vesselfinder gebruiken als waterkaart?',a:['Nee, Vesselfinder is geen waterkaart en vervangt geen nautische kaart','Ja, als de app actueel is en de AIS-gegevens kloppen','Ja, mits je telefoon volledig is opgeladen en je bereik hebt','Alleen in zone 4, want daar is geen nautische kaart nodig'],u:'Vesselfinder is géén waterkaart en vervangt geen nautische kaart.',p:13},
  {q:'Welk rijtje bevat alleen verplichte documenten aan boord?',a:['CVO, vaarbewijs of EU-certificaat, marifoonbewijs, BPR en waterkaart','CVO, vaarbewijs, marifoonbewijs, passagierslijst en paspoort','Vaarbewijs, marifoonbewijs, Verordening 2010, BPR en rijbewijs','CVO, BPR, waterkaart, tachograafuitdraai en Vesselfinder'],u:'Verplicht zijn: het CVO, vaarbewijs of EU-certificaat, marifoonbewijs, BPR en een waterkaart.',p:13},
  {q:'Mogen het CVO, je vaarbewijs, je marifoonbewijs, het BPR en de waterkaart digitaal aan boord zijn?',a:['Ja, zolang ze direct raadpleegbaar zijn aan boord','Nee, het CVO en je vaarbewijs moeten altijd op papier','Alleen het BPR en de waterkaart mogen digitaal zijn','Ja, ook als ze alleen thuis of op kantoor te raadplegen zijn'],u:'Documenten mogen fysiek of digitaal aanwezig zijn, zolang ze direct raadpleegbaar zijn aan boord.',p:13},
  {q:'Wat is de Verordening 2010?',a:['Een lokale wet van de gemeente Amsterdam voor de Amsterdamse binnenwateren','Een Europese richtlijn voor alle binnenvaart in de Europese Unie','De nieuwe naam van het BPR sinds de herziening in 2010','Een landelijke wet van Rijkswaterstaat voor alle Nederlandse grachten'],u:'De Verordening 2010 is een lokale wet van de gemeente Amsterdam en geldt alleen op de Amsterdamse binnenwateren.',p:11},
  {q:'Hoort de Verordening 2010 bij de CBR-exameneisen voor Schipper open rondvaartboot?',a:['Nee, maar kennis ervan is raadzaam voor bedrijfsmatig varen in Amsterdam','Ja, je moet de verordening voor het examen uit je hoofd kennen','Ja, de verordening vervangt het BPR op de Amsterdamse grachten','Nee, en de verordening is ook niet van belang voor de rondvaart'],u:'De verordening is niet opgenomen in de exameneisen van het CBR, maar kennis ervan is wel raadzaam.',p:11},
  {q:'Wat laat de scheepsadministratie zien?',a:['Dat het schip goedgekeurd, vergund en veilig inzetbaar is','Hoeveel omzet en passagiers het schip per jaar heeft','Welke route en welke schipper vandaag zijn ingepland','Welke onderhoudsbeurten de motor binnenkort krijgt'],u:'De scheepsadministratie laat zien dat het schip goedgekeurd, vergund en veilig inzetbaar is.',p:10},
  {q:'Welk logboek heeft een open sloep?',a:['Geen vaartijdenboek, wel een logboek dat de vaart vastlegt (zoals L1nda)','Een vaartijdenboek met rusttijden, zoals bij de grote binnenvaart','Geen logboek: bij open sloepen is geen registratie nodig','Een scheepsjournaal met positie en koers, zoals in de zeevaart'],u:'Bij open sloepen is er geen vaartijdenboek, maar wel een logboek waarin staat dat de boot vaart.',p:10},
  {q:'Wat kan het CBR tijdens het examen over het CVO vragen?',a:['Waar het ligt, wat erin staat, tot wanneer het geldig is en welke beperkingen gelden','Wie het schip heeft gebouwd, op welke werf, in welk jaar en voor welke prijs','Wat de verzekering dekt, wie de eigenaar is en wat het schip heeft gekost','Welke keurder het heeft getekend, zijn telefoonnummer en de datum van aanvraag'],u:'Je kunt gevraagd worden het CVO aan te wijzen, uit te leggen wat erin staat, te laten zien tot wanneer het geldig is en de beperkingen toe te lichten.',p:12}
 ]},
{id:'gebied',t:'Kennis vaargebied',kort:'Zones, waterstand en vaarweginformatie',p:15,
 intro:'Als schipper moet je weten waar je vaart en wat daar wel en niet is toegestaan. Het gaat niet alleen om de route, maar ook om inzicht in zones, waterstand, bruggen en actuele vaarweginformatie.',
 les:[
  {t:'Zones (zone 1 t/m 4)',p:16,b:['Het vaarwater in Nederland is ingedeeld in zones. Die geven aan onder welke omstandigheden een schip veilig mag varen, op basis van golfhoogte, windinvloed en beschutting.',['**Zone 1 en 2**: open en ruige wateren met veel wind en golfslag. Niet bedoeld voor open rondvaartboten.','**Zone 3**: ruimer binnenwater, zoals grote meren en brede wateren. Er is beschutting, maar wind en passerende schepen kunnen golfslag geven.','**Zone 4**: beschut binnenwater, zoals grachten, kanalen en rivieren. Hier varen open rondvaartboten, waaronder op de Amsterdamse grachten.'],{tip:'De zone waarin een schip mag varen staat altijd **in het CVO**. Je mag alleen in de goedgekeurde zone varen; dat heeft direct te maken met de veiligheid en stabiliteit van het schip.'}]},
  {t:'Waterstand en vaargedrag',p:17,b:['De waterstand heeft directe invloed op het varen. Bij hoge of lage waterstand verandert de doorvaarthoogte bij bruggen en kan er minder ruimte zijn in smalle vaarwegen. Ook aan- en afmeren kan lastiger worden.','De waterstand in Amsterdam wordt gemeten ten opzichte van het **Normaal Amsterdams Peil (NAP)**. De standaard waterstand op de grachten is ongeveer **−40 cm ten opzichte van NAP**.','De actuele waterstand vind je:',['op de website van **Rijkswaterstaat**, meetpunt **Surinamekade**','via **Teletekst pagina 720**'],'Staat het water hoger, dan is de ruimte onder een brug kleiner.']},
  {t:'Vaarweginformatie',p:18,b:['Je hoeft niet alles uit je hoofd te weten, maar wel waar je informatie vindt.',['**Nautische (water)kaarten**: vaarwegen, snelheden, zones, doorvaarthoogtes en meldpunten.','**Vaarweginformatie.nl**: actuele stremmingen, waterstanden, werkzaamheden en bijzonderheden op het vaarwater.'],'Het CBR kan vragen waar je deze informatie vandaan haalt en hoe je die gebruikt bij het plannen van een route.']},
  {t:'Route- en tijdsplanning',p:18,b:['Rondvaartboten varen vaak volgens een vast schema. Maak daarom een goede inschatting van de **benodigde vaartijd**. Daarbij spelen afstand en vaarsnelheid mee, maar ook drukte, wachttijden bij bruggen en knelpunten.','Je moet kunnen uitleggen **waarom** je voor een route kiest en hoe je tot een realistische tijdsplanning komt. Het CBR kijkt vooral naar **inzicht en onderbouwing**.']},
  {t:'Bruggen en kunstwerken',p:19,b:['Een **kunstwerk** is een door mensen aangelegde constructie in of over het water: bruggen, sluizen, kades, stuwen en steigers. Ze kunnen beperkingen geven in hoogte, breedte of doorgang.','Let bij het plannen van een route op:',['doorvaarthoogtes van bruggen','eventuele brugopeningen','openingstijden','het marifoonkanaal of telefoonnummer om een brugopening aan te vragen'],'In drukke gebieden en smalle passages denk je vooruit over wachttijden, tegenliggers en de manoeuvres die je moet uitvoeren.']}
 ],
 cbr:['Waar kun je actuele vaarweginformatie vinden?','Wat betekent de waterstand voor jouw vaargedrag?','Hoe controleer je de actuele waterstand?','Wat zijn de belangrijkste risico’s in jouw vaargebied?','Wat moet je weten over bruggen voordat je een route gaat varen?','Wat betekenen de zones 1 t/m 4 en waarom zijn die belangrijk?','Als de waterstand hoger is, is de ruimte onder een brug dan groter of kleiner?'],
 v:[
  {q:'In welke zone varen open rondvaartboten, zoals op de Amsterdamse grachten?',a:['Zone 1','Zone 2','Zone 3','Zone 4'],goed:3,vast:true,u:'Zone 4 is beschut binnenwater zoals grachten, kanalen en rivieren. Daar varen open rondvaartboten.',p:16},
  {q:'Wat zijn zone 1 en 2?',a:['Open en ruige wateren met veel wind en golfslag','Beschut binnenwater, zoals grachten, kanalen en rivieren','Smalle kanalen en sluizen waar alleen beroepsvaart mag varen','Havens en jachthavens waar je alleen stapvoets mag varen'],u:'Zone 1 en 2 zijn open en ruige wateren. Ze zijn niet bedoeld voor open rondvaartboten.',p:16},
  {q:'Wat kenmerkt zone 3?',a:['Ruimer binnenwater, zoals grote meren, waar toch golfslag kan ontstaan','Open en ruig water met veel wind en hoge golven, zoals de zee','Beschut binnenwater, zoals grachten, waar vrijwel geen golfslag is','Smalle kanalen en sluizen waar alleen beroepsvaart mag varen'],u:'Zone 3 is ruimer binnenwater. Er is beschutting, maar wind en passerende scheepvaart kunnen golfslag geven.',p:16},
  {q:'Waar staat in welke zone een schip mag varen?',a:['In het CVO van het schip','Op vaarweginformatie.nl','In het logboek van het schip','In de Verordening 2010'],u:'De zone waarin een schip mag varen staat altijd vermeld in het CVO.',p:16},
  {q:'Ten opzichte waarvan wordt de waterstand in Amsterdam gemeten?',a:['Het Normaal Amsterdams Peil (NAP)','De bodem van de gracht','De bovenkant van de kademuur','Het laagste punt van de brugbogen'],u:'De waterstand wordt gemeten ten opzichte van het Normaal Amsterdams Peil (NAP).',p:17},
  {q:'Wat is ongeveer de standaard waterstand op de grachten?',a:['−40 cm ten opzichte van NAP','+40 cm ten opzichte van NAP','Precies 0 cm NAP','−1 meter ten opzichte van NAP'],u:'De standaard waterstand op de grachten is ongeveer −40 cm ten opzichte van NAP.',p:17},
  {q:'Waar vind je de actuele waterstand?',a:['Op de site van Rijkswaterstaat (meetpunt Surinamekade) of Teletekst pagina 720','Op Vesselfinder, in het logboek of in de dienstregeling','In het CVO, bij het onderdeel over het vaargebied en de belading','Op de nautische waterkaart, bij de doorvaarthoogtes van de bruggen'],u:'Kijk bij Rijkswaterstaat met meetpunt Surinamekade, of op Teletekst pagina 720.',p:17},
  {q:'Het water staat hoger dan normaal. Wat betekent dat voor bruggen?',a:['Er is minder ruimte onder de brug','Er is meer ruimte onder de brug','De ruimte onder de brug blijft gelijk','Bruggen gaan dan vaker automatisch open'],u:'De waterstand verandert de doorvaarthoogte. Staat het water hoger, dan is de ruimte onder een brug kleiner.',p:17},
  {q:'Welke actuele informatie vind je op vaarweginformatie.nl?',a:['Stremmingen, waterstanden, werkzaamheden en bijzonderheden','Passagierslijsten, vertrektijden en ligplaatsen van rederijen','Keuringsdata van schepen, brandblussers en reddingsmiddelen','Vergunningen, tarieven en openingstijden van opstapplaatsen'],u:'Vaarweginformatie.nl geeft actuele informatie zoals stremmingen, waterstanden, werkzaamheden en bijzonderheden.',p:18},
  {q:'Wat staat er op een nautische (water)kaart?',a:['Vaarwegen, snelheden, zones, doorvaarthoogtes en meldpunten','Stremmingen, werkzaamheden en de waterstand van vandaag','Ligplaatsen, tarieven en vergunningen van de rederijen','Bezienswaardigheden, horeca en openbare toiletten langs het water'],u:'Op nautische kaarten staan vaarwegen, snelheden, zones, doorvaarthoogtes en meldpunten.',p:18},
  {q:'Wat is een kunstwerk in de scheepvaart?',a:['Een aangelegde constructie in of over het water, zoals een brug, sluis, kade, stuw of steiger','Een kunstobject langs het water, zoals een beeld, een gevelsteen of een muurschildering','Een natuurlijk obstakel in het water, zoals een zandbank, een eiland of een ondiepte','Een bijzonder schip, zoals een historische rondvaartboot, een tjalk of een woonboot'],u:'Een kunstwerk is een door mensen aangelegde constructie in of over het water die invloed heeft op de scheepvaart.',p:19},
  {q:'Waar let je op bij bruggen als je een route plant?',a:['Doorvaarthoogte, brugopeningen, openingstijden en het marifoonkanaal of telefoonnummer','De naam, het bouwjaar, de architect en de kleur van de brug','Het aantal fietsers, de straatverlichting en de verkeerslichten op de brug','De brugnummers, de straatnamen en de dichtstbijzijnde parkeerplaats'],u:'Let op doorvaarthoogtes, brugopeningen, openingstijden en hoe je een opening aanvraagt (marifoonkanaal of telefoon).',p:19},
  {q:'Waar kijkt het CBR vooral naar bij je route- en tijdsplanning?',a:['Naar inzicht en onderbouwing van je keuzes','Naar de kortst mogelijke route','Naar een route van precies een uur','Naar een route langs zo veel mogelijk bezienswaardigheden'],u:'Het CBR kijkt niet alleen naar kennis, maar vooral naar inzicht en onderbouwing.',p:18},
  {q:'Wat speelt mee bij het inschatten van de benodigde vaartijd?',a:['Afstand, vaarsnelheid, drukte, wachttijden bij bruggen en knelpunten','Afstand en vaarsnelheid; drukte en bruggen tellen niet mee','Aantal passagiers, lengte van het schip en het soort rondvaart','De afstand gedeeld door de maximale snelheid van het schip'],u:'Afstand en snelheid spelen mee, maar ook drukte, wachttijden bij bruggen en knelpunten in het vaargebied.',p:18}
 ]},
{id:'reis',t:'Voorbereiding reis',kort:'Rondgang schip en vaarklaar maken',p:21,
 intro:'Een goede vaart begint vóórdat je losgooit. Als schipper ben je verantwoordelijk voor de staat van het schip en de veiligheid van je passagiers. Daarom controleer je vóór vertrek altijd het schip op vijf vaste onderdelen.',
 les:[
  {t:'Rondgang schip',p:22,b:['Tijdens de rondgang laat je zien dat je het schip kent, veilig werkt en begrijpt wat je controleert. Het gaat niet alleen om aanwijzen, maar vooral om **uitleggen wat je doet en waarom**. Je benoemt hardop wat je controleert en laat het zien aan de examinator.','Er zijn vijf hoofdonderdelen:',['**Stuurhuis**: onder andere je dashboard','**Motorruimte**: onder het luik, inclusief de **schroef** en aandrijving','**Veiligheid**: de veiligheidsmiddelen aan boord','**Salon**: schoon schip maken','**Dek**']]},
  {t:'Het stuurhuis',p:23,b:['Voordat je losgooit controleer je de bediening en systemen:',['**Gas** vooruit en achteruit slaan (gevoel en reactie controleren)','**AIS** aan en correct ingesteld?','**Navigatieverlichting**','**Marifoon(s)** inschakelen en juiste kanaal','**Stuurwiel** (vrij bewegen, geen speling)','**Hydrauliek**','**Hoorn** / geluidssein testen','**Accu- of batterijlading**','**Roeruitslagmeter**','**Snelheidsmeter** (niet aanwezig? Gebruik een navigatie-app als alternatief)','**Bilgepomp** (automatisch en handmatig indien mogelijk)'],{tip:'Alles **benoemen** en zichtbaar maken. Niet alleen zeggen “dit werkt”, maar ook laten zien dat het werkt.'}]},
  {t:'Motorruimte',p:24,b:['Open de motorruimte veilig (bijvoorbeeld het luik onder de stoel). Controlepunten:',['Is de **motorruimte droog**?','Geen olie- of brandstoflekkage zichtbaar?','Nogmaals de **bilge** controleren','Slangen en verbindingen','**Accu’s** visueel controleren'],'Schroefas:',['Controle op lekkage bij de **schroefas**','Uitleg over **smering**: watergesmeerd of vetgesmeerd','Aansluiting **tachograaf** op de aandrijfas'],'Je moet kunnen uitleggen waarom smering belangrijk is: het voorkomt **oververhitting en slijtage**.']},
  {t:'Motorruimte: schroef en aandrijving',p:25,b:['De schroef hoort bij de controle van de motorruimte. Laat zien dat je begrijpt hoe de schroef werkt: wat is de draairichting en hoe controleer je dat?','De beste manier: open het **luik van de motorruimte** en kijk **met weinig gas** hoe de **schroefas** draait.',{tip:'Kijkrichting: **van achteren naar voren** (alsof je achter het schip staat en naar voren kijkt). Zo gezien draait een **rechtsdraaiende** schroefas (met een rechtsdraaiende schroef) bij **vooruit** varen **rechtsom** (met de klok mee) en bij **achteruit** varen **linksom** (tegen de klok in). Kijk je vanuit het schip naar achteren, dan zie je het precies andersom. Bij een linksdraaiende as is alles precies omgekeerd. Houd afstand van de draaiende as: geen losse kleding, sjaals of lange haren in de buurt.'},'Andere manieren om het te controleren:',['Achteruit slaan en kijken naar het **wieleffect**: bij een rechtsdraaiende schroef verzet het achterschip naar bakboord','De bladen bekijken (indien zichtbaar)'],{img:'schroef',alt:'Schroef met drie bladen en rechtse draairichting'}]},
  {t:'Veiligheid',p:68,b:['Controleer de veiligheidsmiddelen aan boord:',['**Reddingsvesten** voor alle passagiers','**Opblaasbare reddingsvesten** voor de bemanning','**Reddingsboeien** aanwezig en bereikbaar','**Brandblusser** gekeurd en druk op peil','**EHBO-doos** compleet en niet over datum','**Pikhaak** aanwezig','**Nooduitgangen** vrij en bekend','**Reddingsmiddelen** bereikbaar']]},
  {t:'Salon / passagiersgedeelte',p:26,b:['Hier verblijven de passagiers. Je controleert of het schip veilig, netjes en gebruiksklaar is:',['Staat van banken en **zitplaatsen**','**Losliggende voorwerpen**','Veiligheid van relingen en instap','Aanwezigheid en bereikbaarheid van **reddingsmiddelen**','**Brandblusser** op de juiste plek','Algemene **netheid en orde**'],'Passagiers moeten veilig kunnen zitten **en zich veilig kunnen verplaatsen**. Obstakels of losse objecten verwijder je vóór vertrek.']},
  {t:'Dek',p:26,b:['Ook het dek controleer je voor vertrek, zodat jij veilig kunt werken en passagiers veilig aan en van boord kunnen:',['Relingen en instap in orde','Geen losse voorwerpen','Lijnen klaar voor het afmeren en aanmeren']]},
  {t:'Checklist: schip vaarklaar maken',p:66,b:['**Administratie**: CVO aanwezig en geldig · vergunning(en) in orde · vaarbewijs en marifoonbewijs · logboek ingevuld · BPR aan boord.','**Voor vertrek**: route en vaargebied bekend · waterstand gecontroleerd · bruggen en bijzonderheden bekend.','**Salon**: schip opgeruimd (zeeklaar) · geen losse spullen · tafels en stoelen vastgezet · verlichting werkt · toilet schoon (indien aanwezig).','**Stuurhuis**: voortstuwing vooruit en achteruit · boegschroef (indien aanwezig) · stuurinrichting · verlichting · marifoon(s) op juiste kanaal · AIS · hoorn · accu’s geladen · noodbesturing bekend · goed zicht rondom (360 graden).','**Motorruimte**: droog en schoon · geen lekkages · oliepeil · koelvloeistof · slangen en verbindingen · bilge en pomp.','**Schroef en aandrijving**: schroef vrij van vuil, touw of plastic · schroefas en smering · draairichting bekend · hydrauliekolie.','**Veiligheid**: reddingsvesten voor alle passagiers · opblaasbare reddingsvesten voor bemanning · reddingsboeien · brandblusser gekeurd en op druk · EHBO-doos compleet · pikhaak · nooduitgangen vrij · reddingsmiddelen bereikbaar.']}
 ],
 cbr:['Wat controleer je voordat je losgooit en waarom is dat belangrijk?','Waar let je op bij het controleren van de motorruimte vóór vertrek?','Hoe controleer je of je schroef en aandrijving correct functioneren?','Wat doe je als je bij de controle water in de bilge aantreft?','Hoe controleer je de draairichting van je schroef en waarom moet je dat weten?','Welke systemen controleer je in het stuurhuis voordat je vertrekt?','Wat betekent “schoon schip maken” en waarom hoort dat bij de reisvoorbereiding?','Wat controleer je in het passagiersgedeelte voordat er gasten aan boord komen?'],
 v:[
  {q:'Wat zijn de vijf hoofdonderdelen van de rondgang over het schip?',a:['Stuurhuis, motorruimte, veiligheid, salon en dek','Stuurhuis, motorruimte, schroef, salon en kade','Stuurhuis, keuken, veiligheid, salon en toilet','Motorruimte, schroef, dek, steiger en meerpalen'],u:'De rondgang bestaat uit stuurhuis, motorruimte, veiligheid, salon en dek.',p:22},
  {q:'Bij welk onderdeel van de rondgang hoort de controle van de schroef?',a:['Bij de motorruimte','Bij het stuurhuis','Bij de salon','Bij het dek'],u:'De schroef en aandrijving horen bij de controle van de motorruimte.',p:24},
  {q:'Wat is belangrijk tijdens de rondgang met de examinator?',a:['Hardop benoemen wat je controleert en laten zien dat het werkt','Alles snel aanwijzen, zodat de examinator ziet dat je het schip kent','Alleen de motor starten en kijken of er geen lampjes branden','Bij elk onderdeel zeggen “dit werkt”, zonder het te laten zien'],u:'Het gaat vooral om uitleggen wat je doet en waarom. Niet alleen zeggen dat het werkt, maar het ook laten zien.',p:23},
  {q:'Waar let je op bij het stuurwiel?',a:['Dat het vrij beweegt en geen speling heeft','Dat het zwaar draait en niet terugveert','Dat het wat speling heeft, zodat je soepel stuurt','Dat het in de middenstand vast kan worden gezet'],u:'Het stuurwiel moet vrij bewegen en mag geen speling hebben.',p:23},
  {q:'Er is geen snelheidsmeter aan boord. Wat doe je?',a:['Een navigatie-app op je telefoon gebruiken als alternatief','De snelheid op gevoel schatten aan de hand van het kielwater','De snelheid aflezen van de toerenteller van de motor','De snelheid opzoeken in het CVO van het schip'],u:'Is er geen snelheidsmeter, gebruik dan een navigatie-app als alternatief.',p:23},
  {q:'Welke controle hoort bij de motorruimte?',a:['Droog, geen olie- of brandstoflekkage, bilge, slangen en verbindingen, accu’s','Reddingsvesten, brandblusser, EHBO-doos, pikhaak en reddingsboeien','Marifoon, AIS, navigatieverlichting, hoorn en roeruitslagmeter','Banken, zitplaatsen, relingen, instap en losliggende voorwerpen'],u:'In de motorruimte controleer je of alles droog is, er geen lekkage is, en bekijk je bilge, slangen, verbindingen en accu’s.',p:24},
  {q:'Waarom is smering van de schroefas belangrijk?',a:['Het voorkomt oververhitting en slijtage','Het zorgt dat de schroef sneller draait','Het vermindert het geluid van de motor','Het bespaart brandstof op lange vaarten'],u:'Je moet kunnen uitleggen dat smering oververhitting en slijtage voorkomt.',p:24},
  {q:'Hoe kan een schroefas gesmeerd zijn?',a:['Watergesmeerd of vetgesmeerd','Luchtgekoeld of oliegekoeld','Met hydrauliekolie uit de besturing','Met koelvloeistof uit de motor'],u:'Een schroefas is watergesmeerd of vetgesmeerd.',p:24},
  {q:'Hoe controleer je de draairichting van de schroef?',a:['Luik openen en met weinig gas naar de schroefas kijken. Van achteren naar voren gezien draait een rechtsdraaiende as bij vooruit rechtsom (met de klok mee) en bij achteruit linksom.','Luik openen en met weinig gas naar de schroefas kijken. Van achteren naar voren gezien draait een rechtsdraaiende as bij vooruit linksom (tegen de klok in) en bij achteruit rechtsom.','Luik openen en met de motor uit de schroefas met de hand ronddraaien. De kant die het makkelijkst draait, is de draairichting bij vooruit varen.','Vol gas vooruit geven en naar het kielwater kijken. Waaiert het water naar stuurboord uit, dan heb je een rechtsdraaiende schroef.'],u:'Open het luik van de motorruimte en kijk met weinig gas naar de schroefas. Van achteren naar voren gezien draait een rechtsdraaiende schroefas bij vooruit varen rechtsom (met de klok mee) en bij achteruit varen linksom (tegen de klok in). Kijk je vanuit het schip naar achteren, dan zie je het precies andersom.',p:25},
  {q:'Wat controleer je aan dek voordat je vertrekt?',a:['Relingen en instap, geen losse voorwerpen, lijnen klaar voor aan- en afmeren','Oliepeil, koelvloeistof, slangen en verbindingen en de bilgepomp','AIS, navigatieverlichting, de hoorn en de roeruitslagmeter in het stuurhuis','Tafels en stoelen vastgezet, toilet schoon en verlichting in de salon'],u:'Aan dek controleer je of de relingen en instap in orde zijn, er geen losse voorwerpen liggen en de lijnen klaarliggen voor het afmeren en aanmeren.',p:26},
  {q:'Wat hoort bij “schoon schip maken” in de salon?',a:['Schip opgeruimd, geen losse spullen, tafels en stoelen vastgezet','De romp van buiten poetsen en de stootwillen binnenhalen','Na afloop van de vaart de ramen en banken schoonmaken','De motorruimte schoonmaken en de bilge leegpompen'],u:'Schoon schip maken betekent: opgeruimd (zeeklaar), geen losse spullen en tafels en stoelen vastgezet.',p:66},
  {q:'Waarop is de tachograaf aangesloten?',a:['Op de aandrijfas','Op de toerenteller','Op de AIS-ontvanger','Op het stuurwiel'],u:'Bij de controle van de schroefas hoort ook de aansluiting van de tachograaf op de aandrijfas.',p:24},
  {q:'Welk punt staat op de checklist van het stuurhuis?',a:['Goed zicht rondom (360 graden)','Tafels en stoelen vastgezet','Toilet schoon en verlichting aan','Oliepeil en koelvloeistof'],u:'Op de checklist van het stuurhuis staat onder andere: goed zicht rondom (360 graden).',p:66}
 ]},
{id:'nav',t:'Navigatie',kort:'Plaats op het water, aanmeren en bochten',p:28,
 intro:'Navigatie gaat over het beheersen van het schip: zelfstandig aan- en afmeren, koersvast varen en de juiste vaartechniek toepassen. Daarbij schat je snelheid en positie goed in, houd je rekening met andere schepen en reageer je rustig op situaties op het water.',
 les:[
  {t:'Extra: de boegschroef',p:30,b:['Veel sloepen hebben een boegschroef. Die kan helpen bij manoeuvreren op lage snelheid. **Binnen de SOR-opleiding hoort de boegschroef niet bij de hoofdbesturing van het schip.**','De hoofdbesturing van onze open rondvaartboten bestaat uit het hydraulische **roer** en de **voortstuwingsschroef**. Die staan in het CVO en daarop is het schip gekeurd. De boegschroef is een aanvullend hulpmiddel.',{tip:'Je moet het schip altijd volledig **zonder boegschroef** kunnen manoeuvreren. Flagship Academy kan niet garanderen dat er tijdens lessen, generale repetities of examens een werkende boegschroef is.'}]},
  {t:'1. Plaats op het water',p:31,b:['Om je plaats te bepalen deel je de waterweg op in banen: eerst doormidden, en daarna de baan waarop je vaart weer in tweeën. De lichte stippellijn is je ideale plaats.',{img:'plaats',alt:'Vier stappen: de waterweg, verdeel, verdeel verder, je plaats'},{tip:'Elke situatie is anders; gebruik dit als uitgangspunt. Hoe smaller de waterweg, hoe dichter je bij de **stuurboordwal** zult moeten varen.'}]},
  {t:'2. Aanmeren zonder wind',p:32,b:['De stappen hieronder gaan uit van aanmeren met **bakboord** langs de kade.',['**Voorbereiding**: vaar rustig op de kant af. Mik met de punt van de boot net achter de kikker waar je wilt aanmeren.','**Stoppen**: stop de boot net voordat je bij de kant bent. Zodra de boot stilligt, draai je het roer naar stuurboord.','**Draaien**: door zachtjes gas te geven laat je de boot draaien. Dreig je te dicht bij de kant te komen, corrigeer dan even in z’n achteruit.'],{img:'aanmeren',alt:'Aanmeren zonder wind in drie stappen'},{tip:'Bij een **rechtsdraaiende schroef** draait je achterschip naar **bakboord** als je achteruit slaat. Bij aanmeren aan bakboord verkleint dat de hoek met de kade tijdens het afstoppen. Aan stuurboord kun je met een kleinere hoek naderen en beweegt de kop bij het afstoppen meer naar de kade.'}]},
  {t:'2. Aanmeren met wind',p:33,b:[['**Lagerwal** (wind naar de kant): kleine hoek als het kan, niet strak langs de kant. Leg de boot bijna parallel stil met wat ruimte; je waait er vanzelf naartoe.','**Wind van de kant af**: neem een grotere hoek dan normaal, anders waai je te snel weg. Pas op dat je niet omwaait als je eerst een achterlijn zet. Gebruik eventueel een voorspring; leg die klaar met de lus achterin.','**Wind van voren**: kleine hoek naar je bestemming en stuur de kop naar de kant. Pas op voor omwaaien bij een achterlijn; eventueel een voorspring.','**Wind van achteren (corrigeren)**: kleine hoek, rustig naar je bestemming. Leg eerst een achterlijn en laat de wind het voorschip bijleggen.'],{img:'aanmeren-wind',alt:'Aanmeren met wind: lagerwal, stoppen, wind van voren, corrigeren'}]},
  {t:'3. Afvaren',p:34,b:['De stappen hieronder gaan uit van een schip dat met **bakboord** aan de kade ligt.',['**Achterkant weg van de kade**: draai het stuurwiel volledig naar bakboord. Met zachtjes gas vooruit beweegt de achterkant weg van de kade. Let op je punt.','**Ruimte maken**: vaar een paar meter achteruit, zodat er ruimte is voor je punt.','**Wegvaren**: stuur volledig naar stuurboord, draai zachtjes weg, zet het roer recht zodra je op koers zit en vaar rechtdoor weg.'],{img:'afvaren',alt:'Afvaren in drie stappen'}]},
  {t:'4. Bocht met vaart',p:35,b:['Bij een ruime bocht hoef je de boot niet stil te leggen. Een bocht met vaart betekent: met **gedoseerde snelheid**, niet met hoge snelheid.',['**Open varen**: zorg dat je zo vroeg mogelijk bent uitgelijnd met de brug, zodat je er recht doorheen vaart.','**Te krap**: je ziet niet wat er aan de andere kant gebeurt en moet onder de brug nog corrigeren. De kans op schade is groot. Zorg dat je de situatie altijd kunt oplossen door de boot stil te leggen.'],{img:'bocht',alt:'Bocht open varen tegenover te krap'},{tip:'Onder de brug: neem een punt in de verte om op af te sturen, dan ga je niet slingeren. Neem de tijd, gebruik weinig gas en maak weinig vaart; het moet ook voor de gasten een comfortabele bocht zijn.'}]},
  {t:'Speciale verrichtingen',p:63,b:['Deze opdrachten kunnen tijdens het examen gevraagd worden:',['Keren op nauw vaarwater','Achteruit door een brug varen','Een MOB-procedure uitvoeren','Vijf scheepslengtes achteruit varen','Afvaren van hoge wal of lage wal','Aanmeren','Voor een brug stilleggen en het schip gaande houden']]}
 ],
 cbr:['Waarom is het belangrijk om een brug “open” te varen?','Wat is schroefwerking en hoe beïnvloedt dit jouw manoeuvres?','Waarom maak je bij manoeuvres meestal zo min mogelijk vaart?','Waar let je op bij het aanmeren van een schip met wind?','Hoe kun je schroefwerking in je voordeel gebruiken?'],
 v:[
  {q:'Hoort de boegschroef bij de hoofdbesturing in de SOR-opleiding?',a:['Nee, het is een aanvullend hulpmiddel; je moet ook zonder kunnen manoeuvreren','Ja, hij staat in het CVO en hoort bij de hoofdbesturing van het schip','Ja, bij het aanmeren en afvaren is de boegschroef verplicht','Alleen bij harde wind; anders hoort hij niet bij de hoofdbesturing'],u:'De boegschroef hoort niet bij de hoofdbesturing; het is een aanvullend hulpmiddel. Je moet het schip zonder boegschroef kunnen manoeuvreren.',p:30},
  {q:'Waaruit bestaat de hoofdbesturing van de open rondvaartboten?',a:['Het hydraulische roer en de voortstuwingsschroef','De boegschroef en het hydraulische roer','De boegschroef en de voortstuwingsschroef','Het roer, de boegschroef en de hekschroef'],u:'De hoofdbesturing bestaat uit het hydraulische roer en de voortstuwingsschroef, zoals vermeld in het CVO.',p:30},
  {q:'Hoe bepaal je je ideale plaats op het water?',a:['Waterweg doormidden delen, en je eigen baan nog eens in tweeën','Altijd precies in het midden van de waterweg varen','Waterweg in drieën delen en in het middelste derde varen','Zo dicht mogelijk langs de stuurboordwal varen'],u:'Deel de waterweg doormidden en daarna je eigen baan nog eens in tweeën. Daar ligt je ideale plaats.',p:31},
  {q:'De waterweg wordt smaller. Wat betekent dat voor je plaats?',a:['Je vaart dichter bij de stuurboordwal','Je vaart dichter bij de bakboordwal','Je vaart precies in het midden','Je houdt dezelfde plaats aan als op breed water'],u:'Hoe smaller de waterweg, hoe dichter je bij de stuurboordwal zult moeten varen.',p:31},
  {q:'Aanmeren zonder wind: waar mik je met de punt van de boot?',a:['Net achter de kikker waar je wilt aanmeren','Precies op de kikker waar je wilt aanmeren','Ruim vóór de kikker waar je wilt aanmeren','Midden tussen twee kikkers in'],u:'Vaar rustig op de kant af en mik met de punt net achter de kikker waar je wilt aanmeren.',p:32},
  {q:'Aanmeren zonder wind, met bakboord langs de kade: de boot ligt net voor de kant stil. Wat doe je?',a:['Roer naar stuurboord en met zachtjes gas de boot laten draaien','Roer naar bakboord en met zachtjes gas de boot laten draaien','Roer recht en met zachtjes gas naar de kant varen','Roer naar stuurboord en vol gas achteruit slaan'],u:'Zodra de boot stilligt draai je het roer naar stuurboord en laat je de boot met zachtjes gas draaien.',p:32},
  {q:'Je hebt een rechtsdraaiende schroef en slaat achteruit. Wat doet het achterschip?',a:['Het draait naar bakboord','Het draait naar stuurboord','Het gaat recht achteruit, zonder te draaien','Eerst naar stuurboord, daarna naar bakboord'],u:'Bij een rechtsdraaiende schroef draait het achterschip naar bakboord als je achteruit slaat.',p:32},
  {q:'Hoe meer je aan bij lagerwal (de wind waait je naar de kant)?',a:['Kleine hoek, bijna parallel stilleggen met wat ruimte; je waait er vanzelf naartoe','Grote hoek en flink vaart houden, anders kom je niet goed bij de kant','Eerst een achterlijn zetten en de wind het voorschip laten bijleggen','Strak langs de kant varen en direct beide lijnen tegelijk vastmaken'],u:'Bij lagerwal leg je de boot bijna parallel stil met een beetje ruimte. De wind drukt je vanzelf tegen de kant.',p:33},
  {q:'De wind waait van de kant af. Hoe meer je aan?',a:['Met een grotere hoek dan normaal, eventueel met een voorspring','Met een kleine hoek, bijna parallel, en dan laten aanwaaien','Eerst een achterlijn zetten en het voorschip laten bijdraaien','Met hoge snelheid en een zo klein mogelijke hoek'],u:'Neem een grotere hoek dan normaal, anders waai je te snel weg. Pas op voor omwaaien en gebruik eventueel een voorspring.',p:33},
  {q:'Je ligt met bakboord aan de kade. Wat is de eerste stap bij het afvaren?',a:['Stuurwiel volledig naar bakboord en zachtjes gas vooruit, zodat de achterkant van de kade komt','Stuurwiel volledig naar stuurboord en zachtjes gas vooruit, zodat de punt van de kade komt','Een paar meter achteruit varen, zodat er ruimte komt voor de punt van de boot','Alle lijnen los en met flink gas vooruit recht van de kade wegvaren'],u:'Draai het stuurwiel volledig naar bakboord en geef zachtjes gas vooruit. De achterkant beweegt weg van de kade.',p:34},
  {q:'Waarom vaar je bij het afvaren een paar meter achteruit?',a:['Om ruimte te maken voor je punt','Om de lijnen makkelijker los te halen','Om de schroef vrij te spoelen van vuil','Om vaart te maken voor de bocht'],u:'Door een paar meter achteruit te varen maak je ruimte voor je punt.',p:34},
  {q:'Waarom vaar je een brug “open”?',a:['Zodat je vroeg bent uitgelijnd en recht door de brug vaart','Zodat je met meer snelheid onder de brug door kunt','Zodat je de bocht pas onder de brug hoeft af te maken','Zodat tegenliggers zien dat je voorrang neemt'],u:'Door open te varen ben je vroeg uitgelijnd en vaar je recht door de brug. Te krap zie je niet wat er aan de andere kant gebeurt.',p:35},
  {q:'Wat betekent “bocht met vaart”?',a:['Met gedoseerde snelheid, niet met hoge snelheid','Met hoge snelheid, zodat de boot goed doordraait','Eerst helemaal stilleggen en dan pas draaien','Met dezelfde snelheid als op de rechte stukken'],u:'Een bocht met vaart betekent met gedoseerde snelheid, niet met hoge snelheid.',p:35},
  {q:'Hoe voorkom je dat je onder een brug gaat slingeren?',a:['Een punt in de verte nemen om op af te sturen','Extra gas geven zodat de boot recht blijft','Het roer vastzetten in de middenstand','Naar de brugpijlers naast je kijken'],u:'Neem onder de brug een punt in de verte om op af te sturen. Zo voorkom je slingeren.',p:35},
  {q:'Waarom maak je bij manoeuvres weinig vaart?',a:['Dan heb je tijd om te corrigeren en is het veiliger en comfortabeler','Dan heeft de wind minder invloed op het schip','Dan reageert het roer sneller en sterker op je stuurbewegingen','Dan hoef je de omgeving minder goed in de gaten te houden'],u:'Elke manoeuvre gaat beter als je de tijd neemt. Met weinig vaart kun je corrigeren en is het comfortabel voor de gasten.',p:35},
  {q:'Welke opdracht hoort bij de speciale verrichtingen?',a:['Vijf scheepslengtes achteruit varen','Tien scheepslengtes achteruit varen','Een ander schip op sleeptouw nemen','Aanmeren met alleen de boegschroef'],u:'Bij de speciale verrichtingen hoort onder andere: vijf scheepslengtes achteruit varen.',p:63}
 ]},
{id:'mari',t:'Marifonie',kort:'Kanalen en het marifoonbericht',p:37,
 intro:'Als schipper moet je de marifoon correct gebruiken en berichten kort, duidelijk en zakelijk houden. Goede communicatie voorkomt misverstanden en zorgt ervoor dat schepen elkaar veilig kunnen passeren of kruisen.',
 les:[
  {t:'Marifoon',p:38,b:['Voorwaarde voor de opleiding is het **basiscertificaat Marifonie**.','Alle beroepsvaartuigen moeten een marifoon hebben; op belangrijke vaarwegen zijn **twee marifoons** verplicht.','Op de Amsterdamse grachten communiceer je met andere schepen op **kanaal 10**. Op de Amstel luister je ook **kanaal 69** uit: het kanaal van de verkeersbegeleiding. Ook binnenvaartschepen communiceren hierop.','De relevante marifoonkanalen zijn **VHF 5, 69 en 10**. De bediening van de verschillende marifoons leer je aan boord (aan/uit, kanaal wisselen, volume, squelch).']},
  {t:'Het marifoonbericht',p:39,b:['Er zijn drie basismanoeuvres die je aankondigt. De opbouw van een bericht is in principe:',['1. **Naam eigen schip**','2. **Huidige locatie**','3. **Waar je heen gaat**']]},
  {t:'Een andere gracht kruisen',p:39,b:['Eigen bootnaam, de gracht waar je op vaart, het woord “kruist” en de gracht die je oversteekt.','Voorbeeld: *“Vibe op de Leliegracht kruist de Keizersgracht.”* of *“Nomag, Prinsen kruist Leidse.”*',{tip:'Komt er geen antwoord, vaar dan **rustig verder**. Een melding is **geen garantie** dat de weg vrij is: schippers missen weleens een melding, of twee schepen melden zich tegelijk. Vaar altijd stapvoets als je een andere gracht oversteekt.'}]},
  {t:'Een andere gracht in',p:40,b:['Eigen bootnaam, de gracht waar je op vaart en de gracht waar je heen gaat.','Voorbeeld: *“Vibe van de Leliegracht naar de Prinsengracht, richting Brouwers.”*','Kun je op die gracht **twee kanten** op, zoals hier, zeg dan altijd welke richting je opgaat. Nog een voorbeeld: *“Nomag, van de Keizers naar de Leidse, richting Heren.”*']},
  {t:'Een andere gracht passeren',p:40,b:['Eigen bootnaam, de gracht waar je op vaart, het woord “passeert” en de gracht waar je langs vaart.','Voorbeeld: *“Nomag, Heren passeert Leidse.”* Je vaart over de Herengracht langs de Leidsegracht, zonder die in te gaan of over te steken.']},
  {t:'Marifoonpunten op de routes',p:41,b:['Een paar vaste routes met hun marifoonpunten. Gebruik ze als voorbeeld voor je eigen casus.',{img:'route-cs',alt:'Centraal Station route met negen marifoonpunten'},{img:'route-af',alt:'Anne Frank route met acht marifoonpunten'},{img:'route-rm',alt:'Rijksmuseum route met negen marifoonpunten'}]},
  {t:'Afspraken maken',p:44,b:['Is het niet duidelijk wie eerst mag of wie waarheen gaat, dan kun je afspraken maken over de marifoon: om verduidelijking vragen, afspreken wie eerst gaat, of elkaar bijvoorbeeld ‘stuurboord stuurboord’ passeren.','Gebruik **altijd officiële termen** en houd het **kort, bondig en zakelijk**. Zo krijgt ander verkeer ook de kans om te communiceren.']}
 ],
 cbr:['Op welk marifoonkanaal wordt meestal gecommuniceerd tussen schepen op de binnenvaart in Amsterdam?','Wanneer ben je verplicht een marifoon te gebruiken tijdens het varen?','Hoe maak je een correcte marifoonoproep naar een ander schip?','Waarom is het belangrijk dat marifoonberichten kort zijn?','Mag je marifoon op 25 W staan?'],
 v:[
  {q:'Op welk kanaal communiceer je met andere schepen op de Amsterdamse grachten?',a:['Kanaal 10','Kanaal 16','Kanaal 69','Kanaal 5'],u:'Op de Amsterdamse grachten wordt met andere schepen gecommuniceerd op kanaal 10.',p:38},
  {q:'Welk kanaal luister je ook uit op de Amstel?',a:['Kanaal 69, van de verkeersbegeleiding','Kanaal 16, het internationale noodkanaal','Kanaal 72, voor contact tussen schepen','Geen extra kanaal, alleen kanaal 10'],u:'Op de Amstel moet ook kanaal 69 worden uitgeluisterd: het kanaal van de verkeersbegeleiding.',p:38},
  {q:'Wat is de opbouw van een marifoonbericht?',a:['Naam eigen schip, huidige locatie, waar je heen gaat','Huidige locatie, tijdstip, naam eigen schip','Naam van het andere schip, het weer, je bestemming','Aantal passagiers, je route, je vaarsnelheid'],u:'In principe: 1. naam eigen schip, 2. huidige locatie, 3. waar je heen gaat.',p:39},
  {q:'Welk bericht is juist als je een andere gracht oversteekt?',a:['“Vibe op de Leliegracht kruist de Keizersgracht.”','“Keizersgracht, Keizersgracht, hier is de Vibe.”','“Vibe gaat zo even de Keizersgracht oversteken.”','“Kruist de Keizersgracht, Vibe, Leliegracht.”'],u:'Eigen bootnaam, gracht waar je op vaart, “kruist”, en de gracht die je oversteekt.',p:39},
  {q:'Je meldt dat je een gracht kruist, maar er komt geen antwoord. Wat doe je?',a:['Rustig en stapvoets verder; een melding is geen garantie dat de weg vrij is','Doorvaren op normale snelheid; je hebt je immers al gemeld','Blijven liggen tot iemand je melding over de marifoon heeft bevestigd','Het bericht nog eens herhalen op kanaal 16 en daarna gewoon doorvaren'],u:'Zonder antwoord vaar je rustig verder, maar een melding garandeert niet dat de weg vrij is. Vaar stapvoets bij het oversteken.',p:39},
  {q:'Je vaart een gracht in waar je twee kanten op kunt. Wat voeg je toe aan je bericht?',a:['Welke richting je opgaat, bijvoorbeeld “richting Heren”','Hoeveel passagiers je op dat moment aan boord hebt','Met welke snelheid je de gracht op gaat varen','Hoe laat je verwacht bij de volgende brug te zijn'],u:'Heeft de gracht twee richtingen, dan geef je ook aan welke van de twee je opgaat.',p:40},
  {q:'Welk bericht hoort bij het passeren van een gracht?',a:['“Nomag, Heren passeert Leidse.”','“Nomag, van de Heren naar de Leidse.”','“Nomag, Heren kruist Leidse.”','“Nomag, hoe is de situatie op de Leidse?”'],u:'Bij passeren noem je je bootnaam, de gracht waar je op vaart, “passeert” en de gracht waar je langs vaart.',p:40},
  {q:'Wanneer zijn twee marifoons verplicht?',a:['Op belangrijke vaarwegen','Op alle Amsterdamse grachten','Alleen bij varen in het donker','Bij meer dan twintig passagiers'],u:'Alle beroepsvaartuigen moeten een marifoon hebben; op belangrijke vaarwegen zijn twee marifoons verplicht.',p:38},
  {q:'Waarom houd je marifoonberichten kort?',a:['Om misverstanden te voorkomen en ander verkeer ook de kans te geven','Omdat de batterij van de marifoon anders snel leeg raakt','Omdat berichten per seconde worden afgerekend door de provider','Omdat de marifoon lange berichten automatisch afbreekt'],u:'Korte, duidelijke berichten voorkomen misverstanden en geven ander verkeer de gelegenheid om te communiceren.',p:44},
  {q:'Wanneer maak je over de marifoon een afspraak met een andere boot?',a:['Als niet duidelijk is wie eerst mag of wie waarheen gaat','Bij elke tegenligger die je op de gracht tegenkomt','Alleen als de verkeersbegeleiding daarom vraagt','Pas nadat je elkaar al bent gepasseerd'],u:'Is het niet duidelijk wie eerst mag of wie waarheen gaat, dan maak je een afspraak over de marifoon: bijvoorbeeld wie eerst gaat, of elkaar ‘stuurboord stuurboord’ passeren. Gebruik officiële termen en houd het kort.',p:44},
  {q:'Welk certificaat is een voorwaarde voor de opleiding tot Schipper open rondvaartboot?',a:['Het basiscertificaat Marifonie','Het Groot Vaarbewijs','Het certificaat Radarpatent','Een geldig EHBO-diploma'],u:'Voorwaarde voor het volgen van de opleiding is dat het basiscertificaat Marifonie behaald is.',p:38},
  {q:'Welke marifoonkanalen noemt de opleiding als relevant?',a:['VHF 5, 69 en 10','VHF 10, 16 en 70','VHF 5, 10 en 16','VHF 69, 72 en 77'],u:'Je moet kennis hebben van de relevante marifoonkanalen VHF 5, 69 en 10.',p:38}
 ]},
{id:'veil',t:'Veiligheid',kort:'Veiligheidsmiddelen en man overboord',p:46,
 intro:'Als schipper ben je verantwoordelijk voor de veiligheid van je passagiers, bemanning en het schip. Je herkent risico’s, schat situaties goed in en weet hoe je handelt bij een incident. Veiligheid begint al vóórdat er iets misgaat.',
 les:[
  {t:'Veiligheidsmiddelen aan boord',p:47,b:['Er moeten altijd voldoende veiligheidsmiddelen aan boord zijn, goed bereikbaar en in goede staat. Je moet weten waar ze liggen en hoe je ze gebruikt.',['**Reddingsvesten** voor alle **passagiers** en **opblaasbare** reddingsvesten voor alle **bemanningsleden**.','**Reddingsboeien**: aanwezig en direct bereikbaar, zodat je er bij een man overboord meteen een naar de drenkeling kunt gooien.','**Brandblusser**: goed bereikbaar en geschikt voor een schip. Controleer of de **keuringsdatum** geldig is en de **drukmeter op groen** staat.','**EHBO-doos**: regelmatig controleren of alle materialen aanwezig zijn en niets over de datum is.','**Pikhaak**: een lange stok met een haak, om voorwerpen uit het water of vuil uit de schroef te halen (zoals een plastic zak) en bij een man-overboordsituatie iemand naar het schip te trekken.'],{tip:'Het is de verantwoordelijkheid van de schipper dat alle veiligheidsmiddelen aan boord **compleet, in goede staat en direct bereikbaar** zijn.'}]},
  {t:'Man-over-boord manoeuvre (MOB)',p:50,b:['Het doel: het slachtoffer snel terugvinden, veilig benaderen en weer aan boord krijgen, zonder extra risico door de schroef.',['1. **Sla alarm**: roep luid “Man overboord!” en zet je **schroef stil**.','2. **Wijs iemand aan** die het slachtoffer blijft volgen: “Jij, wijs naar de drenkeling.” Zo raak je de persoon niet uit het oog.','3. Gooi een **reddingsboei** naar de drenkeling en roep “Zwem”.','4. Manoeuvreer snel maar voorzichtig terug **naar de persoon**. Zijn er andere schepen in de buurt, meld dan via de **marifoon** dat er iemand overboord is.','5. Trek de persoon naar het schip met de **pikhaak** en help hem **aan boord** via een trap, de rand of met hulp van de bemanning.','6. **Controleer direct de toestand**: bewustzijn en ademhaling, verleen eerste hulp indien nodig (bijvoorbeeld met isolatiedeken) en bel **112** als medische hulp nodig is.']]},
  {t:'In- en uitstappen',p:51,b:['Veel incidenten gebeuren bij het in- en uitstappen.',['**De schipper**: stap je zelf van of aan boord om lijnen vast te maken, dan draag je **altijd een draagbaar (opblaasbaar) reddingsvest**.','**Passagiers**: het schip ligt stabiel en goed vast (**minimaal 2 lijnen**) voordat passagiers aan of van boord gaan. De afstand tussen wal en schip is zo klein mogelijk.']]}
 ],
 cbr:['Wat doe je als iemand overboord valt?','Wat doe je als je merkt dat iemand uit het water niet meer ademt?','Wat zijn de eerste stappen bij brand aan boord?','Wat doe je als je een rotte-eierenlucht ruikt aan boord?','Waarom is een schoon schip belangrijk voor de veiligheid?','Welke veiligheidsmiddelen moeten er minimaal aan boord zijn?','Waar let je op bij het instappen van passagiers?','Waarom is het belangrijk om passagiers vooraf instructies te geven?'],
 v:[
  {q:'Iemand valt overboord. Wat is je eerste stap?',a:['Alarm slaan (“Man overboord!”) en de schroef stilzetten','Direct achteruit varen naar de persoon in het water','Eerst 112 bellen en daarna de schroef stilzetten','Een reddingsboei gooien en daarna pas alarm slaan'],u:'Sla direct alarm door luid “Man overboord!” te roepen, en zet je schroef stil.',p:50},
  {q:'Waarom wijs je iemand aan die naar de drenkeling blijft wijzen?',a:['Zodat je de persoon in het water niet uit het oog verliest','Zodat die persoon de reddingsboei naar de drenkeling gooit','Zodat de andere passagiers rustig blijven en niet gaan kijken','Zodat de verkeersbegeleiding weet waar het ongeluk is'],u:'Door iemand te laten blijven wijzen, raak je de drenkeling niet uit het oog.',p:50},
  {q:'Wat gooi je naar de drenkeling?',a:['Een reddingsboei, en je roept “Zwem”','De pikhaak, en je roept “Pak vast”','Een landvast, en je roept “Trek”','Een reddingsvest, en je roept “Wacht”'],u:'Gooi een reddingsboei naar de drenkeling en roep “Zwem”.',p:50},
  {q:'Wanneer meld je een man overboord via de marifoon?',a:['Als er andere schepen in de buurt zijn','Nooit, want dat leidt je af van de redding','Pas als de persoon weer aan boord is','Alleen als de persoon niet kan zwemmen'],u:'Zijn er andere schepen in de buurt, geef dan via de marifoon aan dat er iemand overboord is.',p:50},
  {q:'Waarvoor gebruik je de pikhaak bij een man overboord?',a:['Om de persoon dichter naar het schip te trekken','Om de schroef te blokkeren zodat hij stopt','Om de plek van de drenkeling aan te wijzen','Om de afstand tot de drenkeling te meten'],u:'Met de pikhaak trek je de persoon dichter naar het schip en help je hem aan boord.',p:50},
  {q:'De persoon is weer aan boord. Wat doe je direct?',a:['Bewustzijn en ademhaling controleren, eerste hulp geven en zo nodig 112 bellen','Droge kleren en een deken geven en de rondvaart gewoon afmaken','Het incident in het logboek zetten en daarna rustig verder varen','Direct terugvaren naar de steiger, zonder de persoon te controleren'],u:'Controleer direct bewustzijn en ademhaling, verleen eerste hulp indien nodig en bel 112 als medische hulp nodig is.',p:50},
  {q:'Waarom zet je bij een man overboord de schroef stil?',a:['Om geen extra risico te veroorzaken voor de persoon in het water','Om brandstof te besparen tijdens het zoeken naar de persoon','Om de marifoonberichten van andere schepen beter te horen','Omdat de motor anders kan oververhitten tijdens het manoeuvreren'],u:'Het doel is het slachtoffer veilig terug aan boord te krijgen zonder extra risico door de schroef.',p:50},
  {q:'Wat controleer je aan de brandblusser?',a:['Of hij bereikbaar is, de keuringsdatum geldig is en de drukmeter op groen staat','Of hij in de motorruimte achter slot ligt, zodat passagiers er niet bij kunnen','Of de drukmeter op rood staat, want dan is hij vol en klaar voor gebruik','Of hij zwaar genoeg is en de kleur overeenkomt met wat in het CVO staat'],u:'De brandblusser moet goed bereikbaar zijn, gekeurd (geldige keuringsdatum) en de drukmeter moet op groen staan.',p:47},
  {q:'Welke reddingsvesten zijn er voor de bemanning?',a:['Opblaasbare reddingsvesten, voor elk bemanningslid','Dezelfde vesten als de passagiers, onder de banken','Geen vest: de bemanning heeft een zwemdiploma','Eén reddingsboei per bemanningslid'],u:'Er moeten reddingsvesten zijn voor alle passagiers en opblaasbare reddingsvesten voor alle bemanningsleden.',p:47},
  {q:'Waar let je op bij de EHBO-doos?',a:['Dat alle benodigde materialen aanwezig zijn en niets over de datum is','Dat hij op slot zit, zodat er niets uit kan verdwijnen','Dat hij in de motorruimte staat, uit het zicht van passagiers','Dat hij verzegeld is en alleen door de keurder geopend wordt'],u:'Controleer regelmatig of alle materialen aanwezig zijn en of producten niet over de datum zijn.',p:48},
  {q:'Wanneer mogen passagiers aan of van boord gaan?',a:['Als het schip stabiel ligt en vastligt met minimaal 2 lijnen','Zodra het schip de kade raakt, ook als er nog geen lijn vastzit','Als er minimaal één lijn vastzit aan de kade','Als de passagiers dat zelf willen, ook als het schip nog beweegt'],u:'Het schip moet stabiel liggen en goed vastgemaakt zijn (minimaal 2 lijnen), met zo weinig mogelijk afstand tussen wal en schip.',p:51},
  {q:'Je stapt zelf van boord om de lijnen vast te maken. Wat draag je?',a:['Altijd een draagbaar (opblaasbaar) reddingsvest','Werkhandschoenen; een vest is aan de kade niet nodig','Alleen een reddingsvest als het donker is','Niets bijzonders, je stapt maar even van boord'],u:'Als de schipper van of aan boord stapt om lijnen vast te maken, draagt hij altijd een draagbaar reddingsvest.',p:51},
  {q:'Wie is verantwoordelijk dat alle veiligheidsmiddelen compleet en bereikbaar zijn?',a:['De schipper','De passagiers zelf','De keurder van het CVO','De gemeente Amsterdam'],u:'Het is de verantwoordelijkheid van de schipper dat alle veiligheidsmiddelen compleet, in goede staat en direct bereikbaar zijn.',p:48},
  {q:'Welk rijtje bevat alleen veiligheidsmiddelen die aan boord moeten zijn?',a:['Reddingsvesten, reddingsboeien, brandblusser, EHBO-doos en pikhaak','Reddingsvesten, reddingsboeien, brandblusser, EHBO-doos en verrekijker','Brandblusser, EHBO-doos, pikhaak, reddingsboeien en een reservemotor','Reddingsvesten, pikhaak, EHBO-doos, reddingsboeien en regenponcho’s'],u:'Aan boord horen onder andere reddingsvesten, reddingsboeien, een brandblusser, een EHBO-doos en een pikhaak. Ze moeten compleet, in goede staat en direct bereikbaar zijn.',p:47}
 ]},
{id:'tech',t:'Scheepstechniek',kort:'Motor, koeling, hydrauliek en bilge',p:53,
 intro:'Je hoeft geen monteur te zijn, maar je moet wel begrijpen hoe het schip werkt en wat je controleert om veilig te varen: de motor, de aandrijving, de stuurinrichting en andere systemen aan boord.',
 les:[
  {t:'Motor en basiscontrole',p:54,b:['De motor is het hart van het schip. Voor vertrek controleer je onder andere:',['Oliepeil','Koelvloeistof','Brandstofniveau','Eventuele lekkages','Slangen en verbindingen'],'Let ook op afwijkingen zoals vreemde geluiden of geuren, en rookontwikkeling of brandlucht.',{tip:'Bij twijfel: **stop** en onderzoek het probleem voordat je verder vaart.'}]},
  {t:'Koeling van de motor',p:54,b:['De motor moet gekoeld worden om oververhitting te voorkomen, meestal met **waterkoeling**. Je moet weten hoe de koeling werkt, waar je kunt zien of er koelwater uitstroomt, en dat een gebrek aan koeling kan leiden tot **motorschade**.']},
  {t:'Schroef en aandrijving',p:55,b:['De schroef zorgt voor de voortstuwing; de aandrijving brengt de kracht van de motor over naar de schroef.',['De schroef kan links- of rechtsdraaiend zijn','De draairichting beïnvloedt je manoeuvres','Vuil of lijnen in de schroef verminderen de werking'],'Je moet weten hoe jouw schip reageert bij vooruit en achteruit slaan.']},
  {t:'Hydrauliek en besturing',p:55,b:['Veel schepen gebruiken hydrauliek voor de besturing. Je moet weten hoe de besturing reageert, dat er voldoende hydrauliekolie is, en dat **lekkages kunnen leiden tot uitval van de besturing**.','Bij problemen met de besturing handel je direct en breng je het schip **veilig tot stilstand**.']},
  {t:'Accu’s en elektriciteit',p:55,b:['Accu’s zijn er voor het starten van de motor en het voeden van de elektrische systemen.',['Accu’s moeten goed geladen zijn','Slechte accu’s kunnen problemen geven bij het starten','Bij accu’s kan **knalgas** ontstaan'],{tip:'Een **rotte-eierenlucht** kan wijzen op een probleem met de accu. Ventileer en wees voorzichtig met vonken of vuur.'}]},
  {t:'Bilge en water in het schip',p:56,b:['De bilge is het **laagste punt** van het schip, waar water zich kan verzamelen. Je controleert of er water in de bilge staat, of de motor droog staat en of de bilgepomp werkt.','Te veel water in het schip kan gevaarlijk zijn en moet **direct** worden aangepakt.']}
 ],
 cbr:['Wat controleer je in de motorruimte voordat je gaat varen?','Wat doe je als er geen koelwater uit de uitlaat komt?','Wat is schroefwerking en hoe merk je dat tijdens het varen?','Hoe kun je zien of je een links- of rechtsdraaiende schroef hebt?','Wat gebeurt er met je schip als er vuil in de schroef zit?','Waar let je op bij het controleren van de hydrauliek?','Wat betekent een rotte-eierenlucht in de motorruimte?','Wat doe je als je merkt dat je besturing niet goed reageert?'],
 v:[
  {q:'Wat controleer je voor vertrek aan de motor?',a:['Oliepeil, koelvloeistof, brandstofniveau, lekkages, slangen en verbindingen','Brandstofniveau, AIS, navigatieverlichting, hoorn en roeruitslagmeter','Alleen of hij goed start en stationair rustig loopt, verder niets','Bouwjaar, vermogen, serienummer en het type brandstof van de motor'],u:'Voor vertrek controleer je onder andere oliepeil, koelvloeistof, brandstofniveau, lekkages en slangen en verbindingen.',p:54},
  {q:'Je hoort een vreemd geluid en ruikt brandlucht. Wat doe je?',a:['Stoppen en het probleem onderzoeken voordat je verder vaart','Doorvaren tot het einde van de rondvaart en het dan melden','Meer gas geven om te horen of het geluid verdwijnt','Een raam openzetten tegen de geur en rustig doorvaren'],u:'Bij twijfel stop je en onderzoek je het probleem voordat je verder vaart.',p:54},
  {q:'Hoe wordt de motor meestal gekoeld?',a:['Met waterkoeling','Met luchtkoeling door een ventilator','Met de hydrauliekolie van de besturing','Niet, een scheepsmotor wordt niet warm'],u:'De motor wordt meestal gekoeld met waterkoeling.',p:54},
  {q:'Hoe kun je tijdens het varen zien of de koeling van de motor werkt?',a:['Er stroomt koelwater uit de uitlaat','Er komt rook uit de uitlaat','De motor maakt meer geluid dan normaal','De bilgepomp slaat vaker aan'],u:'Bij waterkoeling stroomt er koelwater uit de uitlaat. Je moet weten waar je dat bij jouw schip kunt zien. Zonder koeling kan de motor oververhit raken en beschadigen.',p:54},
  {q:'Er komt geen koelwater uit de uitlaat. Wat doe je?',a:['Stoppen en onderzoeken: zonder koeling kan de motor beschadigen','Harder varen, zodat er meer koelwater wordt aangezogen','Doorvaren en de koelvloeistof na de rit bijvullen','Niets doen; bij waterkoeling is dat heel normaal'],u:'Je moet weten waar je kunt zien of er koelwater uitstroomt. Een gebrek aan koeling kan motorschade geven; bij twijfel stop en onderzoek je.',p:54},
  {q:'Wat doet de aandrijving?',a:['Brengt de kracht van de motor over naar de schroef','Levert stroom aan de verlichting en de marifoon','Koelt de motor met water van buitenboord','Stuurt het schip naar bakboord of stuurboord'],u:'De aandrijving brengt de kracht van de motor over naar de schroef.',p:55},
  {q:'Wat gebeurt er als er vuil of een lijn in de schroef zit?',a:['De werking van de schroef vermindert','Het schip gaat juist sneller varen','Er verandert niets aan de werking','De boegschroef neemt het automatisch over'],u:'Vuil of lijnen in de schroef verminderen de werking.',p:55},
  {q:'Waarom is een lekkage in de hydrauliek gevaarlijk?',a:['Het kan leiden tot uitval van de besturing','Het kan leiden tot uitval van de marifoon','Het zorgt ervoor dat de motor gaat roken','Het laat de bilgepomp continu draaien'],u:'Veel schepen sturen hydraulisch. Lekkages kunnen leiden tot uitval van de besturing.',p:55},
  {q:'Je besturing reageert niet goed. Wat doe je?',a:['Direct handelen en het schip veilig tot stilstand brengen','Doorvaren en het na de rit melden bij de rederij','Harder gas geven, zodat het roer beter reageert','Alleen nog met de boegschroef sturen en doorvaren'],u:'Bij problemen met de besturing handel je direct en breng je het schip veilig tot stilstand.',p:55},
  {q:'Je ruikt een rotte-eierenlucht aan boord. Waar kan dat op wijzen?',a:['Een probleem met de accu: ventileren en voorzichtig zijn met vonken of vuur','Lekkende koelvloeistof: na de vaart het koelsysteem bijvullen','Te veel koelwater: de motor even stationair laten draaien','Een bijna lege tank: na de vaart brandstof bijvullen'],u:'Een rotte-eierenlucht kan wijzen op een probleem met de accu, bijvoorbeeld door overladen. Daarbij kan ook knalgas vrijkomen. Ventileer en wees voorzichtig met vonken of vuur.',p:55},
  {q:'Wat is de bilge?',a:['Het laagste punt van het schip, waar water zich verzamelt','Het hoogste punt van het schip, boven het stuurhuis','De ruimte achterin waar de schroefas naar buiten gaat','De tank waarin het koelwater voor de motor zit'],u:'De bilge is het laagste punt van het schip waar water zich kan verzamelen.',p:56},
  {q:'Er staat te veel water in het schip. Wat doe je?',a:['Direct aanpakken, want het kan gevaarlijk zijn','Na de vaart bekijken, als de passagiers van boord zijn','Wachten tot de bilgepomp het vanzelf wegpompt','Negeren zolang de motor nog goed loopt'],u:'Te veel water in het schip kan gevaarlijk zijn en moet direct worden aangepakt.',p:56},
  {q:'Waarvoor zijn de accu’s aan boord?',a:['Voor het starten van de motor en het voeden van de elektrische systemen','Alleen voor de muziek en de verlichting in het passagiersgedeelte','Voor het koelen van de motor tijdens lange vaarten','Om de hydrauliekolie van de besturing op temperatuur te houden'],u:'Accu’s zijn aan boord voor het starten van de motor en het voeden van elektrische systemen.',p:55}
 ]},
{id:'soc',t:'Sociale vaardigheden',kort:'Instructie, gastheerschap en sociale hygiëne',p:57,
 intro:'Als schipper ben je niet alleen verantwoordelijk voor het varen, maar ook voor de ervaring aan boord. Je bent het aanspreekpunt voor passagiers en zorgt voor een veilige, prettige en professionele sfeer.',
 les:[
  {t:'Passagiersinstructie',p:58,b:['Voordat je vertrekt geef je duidelijke basisinstructies. Zo voorkom je onrust en gevaarlijke situaties. Dit moet er **altijd** in zitten:',['Stel jezelf (en eventuele andere bemanning) voor en maak duidelijk dat jij de **eindverantwoordelijke** bent aan boord','Beschrijf de **vaart** die je gaat doen','Houd tijdens het varen **alles binnenboord**: geen handen, armen of andere lichaamsdelen buiten het schip','Let op bij lage **bruggen**: blijf zo veel mogelijk zitten en wees je bewust van je omgeving','**Reddingsvesten** liggen onder de banken','De **nooduitgangen** zijn op [locatie aan boord]','Volg altijd de **instructies** van de schipper en bemanning op'],'Verdere instructies hangen af van de vaart, de rederij en het type tour.']},
  {t:'Gastheerschap en gastvrouwschap',p:59,b:['Je bent **vriendelijk, attent en behulpzaam** richting passagiers en zorgt dat gasten zich welkom voelen. Je houdt rekening met verschillende gasten, zoals toeristen, gezinnen of groepen.','Je speelt in op wensen van passagiers waar dat kan, **zonder dat het ten koste gaat van de veiligheid**. Je begrijpt en beantwoordt eenvoudige vragen en opmerkingen.']},
  {t:'Presentatietechnieken',p:59,b:['Je brengt informatie over met een **welkomstpraatje** en een **gidsenpraatje**. Bij aanvang heet je passagiers welkom en deel je eventueel praktische informatie; tijdens de vaart vertel je over de omgeving en bezienswaardigheden.','Dit moet je kunnen in het **Nederlands en Engels**.']},
  {t:'Sociale hygiëne',p:60,b:['Je bent verantwoordelijk voor een **sociaal veilige omgeving** aan boord. Je houdt toezicht op het gedrag van passagiers en grijpt in wanneer dat nodig is, bijvoorbeeld bij overmatig alcoholgebruik, ongewenst gedrag of spanningen tussen passagiers.','Je past de regels van sociale hygiëne toe door:',['duidelijk grenzen te stellen','respectvol te communiceren','escalaties te voorkomen'],'Het doel: iedereen aan boord voelt zich veilig en de vaart verloopt zonder problemen.']}
 ],
 cbr:['Hoe zorg jij ervoor dat passagiers zich welkom voelen aan boord?','Wat doe je als een passagier zich onveilig gedraagt?','Hoe spreek je een passagier aan op ongewenst gedrag?','Wat vertel je in een welkomstpraatje aan het begin van de vaart?','Waarom is het belangrijk om in meerdere talen te kunnen communiceren?','Wat betekent sociale hygiëne aan boord van een schip?','Wat doe je als er spanning ontstaat tussen passagiers?'],
 v:[
  {q:'Welk punt hoort ALTIJD in de passagiersinstructie?',a:['Houd alles binnenboord: geen handen of armen buiten het schip','De geschiedenis van de rederij en de bouw van het schip','Het menu en de prijzen van de drankjes aan boord','De bouwjaren van de grachtenpanden onderweg'],u:'Vast onderdeel van de instructie: houd tijdens het varen alles binnenboord.',p:58},
  {q:'Waar liggen de reddingsvesten volgens de standaardinstructie?',a:['Onder de banken','In het stuurhuis, achter slot','In de motorruimte, onder het luik','Op de kade, bij de steiger'],u:'In de instructie vertel je dat de reddingsvesten onder de banken liggen.',p:58},
  {q:'Wat zeg je in de instructie over lage bruggen?',a:['Blijf zo veel mogelijk zitten en wees je bewust van je omgeving','Ga even staan, dan kun je de brug van dichtbij bekijken','Steek je hand omhoog om afstand te houden van de brug','Ga aan de rand zitten, daar is meer ruimte onder de brug'],u:'Let op bij lage bruggen: blijf zo veel mogelijk zitten en wees je bewust van je omgeving.',p:58},
  {q:'Wie maak je in de instructie duidelijk als eindverantwoordelijke aan boord?',a:['Jezelf, de schipper','De gids aan boord','De oudste passagier','De rederij aan de wal'],u:'Stel jezelf voor en maak duidelijk dat jij de eindverantwoordelijke bent aan boord.',p:58},
  {q:'Waarom geef je vooraf een passagiersinstructie?',a:['Om onrust en gevaarlijke situaties tijdens het varen te voorkomen','Om de tijd tot vertrek op een gezellige manier op te vullen','Om passagiers te laten merken hoeveel je van de stad weet','Om aan het einde van de vaart een hogere fooi te krijgen'],u:'Door vooraf heldere afspraken te maken voorkom je onrust en gevaarlijke situaties.',p:58},
  {q:'In welke talen moet je je welkomst- en gidsenpraatje kunnen doen?',a:['Nederlands en Engels','Alleen Nederlands','Alleen Engels','Nederlands, Duits en Frans'],u:'Je moet het welkomstpraatje en gidsenpraatje in het Nederlands en Engels kunnen doen.',p:59},
  {q:'Wat betekent gastheerschap?',a:['Vriendelijk, attent en behulpzaam zijn, zonder dat het ten koste gaat van de veiligheid','Alles doen wat passagiers vragen, ook als het de vaart minder veilig maakt','Zo min mogelijk met passagiers praten, zodat je je kunt concentreren','Vooral aandacht geven aan vaste klanten en grote groepen'],u:'Je bent vriendelijk, attent en behulpzaam en speelt in op wensen, maar nooit ten koste van de veiligheid.',p:59},
  {q:'Wat is sociale hygiëne aan boord?',a:['Zorgen voor een sociaal veilige omgeving: grenzen stellen, respectvol communiceren, escalaties voorkomen','Zorgen voor een schoon schip: het toilet, de banken, de tafels en de ramen netjes houden','Zorgen voor persoonlijke hygiëne: handen wassen, schone kleding dragen en niet roken','Zorgen voor een gezellige sfeer: muziek, drankjes, grapjes en veel interactie met gasten'],u:'Sociale hygiëne gaat over een sociaal veilige omgeving: duidelijk grenzen stellen, respectvol communiceren en escalaties voorkomen.',p:60},
  {q:'Een passagier drinkt te veel en gedraagt zich ongewenst. Wat doe je?',a:['Toezicht houden en ingrijpen: duidelijk en respectvol grenzen stellen','Niets doen: passagiers mogen zelf weten hoeveel ze drinken','De rest van de groep vragen het zelf onderling op te lossen','Meer drinken schenken, zodat de sfeer gezellig blijft'],u:'Je houdt toezicht en grijpt in als het nodig is, bijvoorbeeld bij overmatig alcoholgebruik of ongewenst gedrag.',p:60},
  {q:'Wat doe je in het welkomstpraatje?',a:['Passagiers welkom heten en eventueel praktische informatie delen','De volledige geschiedenis van Amsterdam vertellen','Alleen de prijzen en de huisregels van de rederij noemen','Niets: meteen beginnen met varen en onderweg uitleggen'],u:'Bij aanvang van de vaart heet je passagiers welkom en deel je eventueel praktische informatie.',p:59}
 ]}
];
